		subs: [
			{ t: 0.00, e: 4.39, en: 'Page 48. Track 21. Listening 3.', vi: '' },
			{ t: 6.32, e: 15.25, en: '1. I could never buy a car at home because we pay a very high tax on cars. Only rich people', vi: '' },
			{ t: 15.10, e: 22.63, en: 'can really afford to buy a car at home. Here in the US I drive a nice new car and I can', vi: '' },
			{ t: 22.48, e: 27.77, en: 'easily afford it. You don\'t have to be rich to own a car which is great.', vi: '' },
			{ t: 29.60, e: 38.09, en: '2. At home it only costs about $300 a month to rent a nice apartment. That\'s what I used', vi: '' },
			{ t: 37.94, e: 44.35, en: 'to pay for a full room apartment in a good neighborhood. Here in the US I pay more than', vi: '' },
			{ t: 44.20, e: 49.81, en: 'twice that for a much smaller apartment and it\'s not in a very nice neighborhood.', vi: '' },
			{ t: 51.58, e: 57.83, en: '3. I bought a lot of clothes in my country before I moved to the US because everyone told', vi: '' },
			{ t: 57.68, e: 62.83, en: 'me how expensive American clothing is. I was kind of surprised that I could get nice', vi: '' },
			{ t: 62.68, e: 68.31, en: 'clothes here for very reasonable prices. In fact it costs me less for clothes here than', vi: '' },
			{ t: 68.16, e: 75.09, en: 'it used to cost me at home. 4. In my country not a lot of people', vi: '' },
			{ t: 74.94, e: 80.19, en: 'travel by plane because it costs more than most people can afford but the US is such a', vi: '' },
			{ t: 80.04, e: 85.27, en: 'big country and the population is large so you have a lot of people traveling by plane.', vi: '' },
			{ t: 85.52, e: 90.31, en: 'That\'s what keeps the prices down. That means I can afford to fly here and I do it all', vi: '' },
			{ t: 90.16, e: 94.99, en: 'the time. I couldn\'t do that at home. 5.', vi: '' },
			{ t: 95.56, e: 100.07, en: 'Most people send their children to private schools at home because the public schools', vi: '' },
			{ t: 99.92, e: 106.05, en: 'are not very good. You have to pay a lot to do that so it\'s a big expense for many people.', vi: '' },
			{ t: 106.44, e: 112.01, en: 'Public schools are better in the US and they\'re free so most people here send their children', vi: '' },
			{ t: 111.86, e: 119.61, en: 'to public schools. 6. Here in the US you need to have health insurance', vi: '' },
			{ t: 119.46, e: 125.45, en: 'because it costs a lot to see a doctor or to enter a hospital. At home you don\'t have', vi: '' },
			{ t: 125.30, e: 130.71, en: 'to pay much to see a doctor or go to a hospital because most of the clinics and hospitals are', vi: '' },
			{ t: 130.56, e: 131.53, en: 'run by the government.', vi: '' },
		]
