		subs: [
			{ t: 0.00, e: 7.57, en: 'Unit 6, GIFs, Page 22, Track 27, Listening 1.', vi: '' },
			{ t: 9.32, e: 12.95, en: '1. Who are you buying a gift for?', vi: '' },
			{ t: 13.42, e: 19.05, en: 'It\'s a present for Annie, to say thank you for helping me with a school project. Any ideas?', vi: '' },
			{ t: 19.56, e: 23.65, en: 'I think some jewelry would be nice, maybe a bracelet?', vi: '' },
			{ t: 24.26, e: 27.23, en: 'I don\'t know. A bracelet sounds expensive.', vi: '' },
			{ t: 27.90, e: 29.29, en: 'How about this keychain?', vi: '' },
			{ t: 29.82, e: 31.07, en: 'That\'s a great idea.', vi: '' },
			{ t: 32.74, e: 37.37, en: '2. Are we getting mom a mother\'s day present this year?', vi: '' },
			{ t: 37.90, e: 41.13, en: 'Of course. I was thinking of getting her some flowers.', vi: '' },
			{ t: 41.80, e: 48.01, en: 'Oh, flowers are nice, but it\'s our mom. We should get her something really special.', vi: '' },
			{ t: 48.72, e: 51.97, en: 'I know. Let\'s get her some really nice jewelry.', vi: '' },
			{ t: 52.44, e: 56.23, en: 'I agree. Let\'s get her that bracelet we saw last week.', vi: '' },
			{ t: 57.88, e: 62.69, en: '3. Are you going to Brandon\'s graduation party, too?', vi: '' },
			{ t: 63.22, e: 66.09, en: 'Yes, and I think we need to bring a gift.', vi: '' },
			{ t: 66.56, e: 69.41, en: 'Oh, that\'s right. For Brandon.', vi: '' },
			{ t: 71.16, e: 73.13, en: 'How about a necktie?', vi: '' },
			{ t: 73.54, e: 77.85, en: 'I don\'t know. I wonder if a tie is really useful.', vi: '' },
			{ t: 78.58, e: 82.11, en: 'You\'re right. I know a pen.', vi: '' },
			{ t: 82.64, e: 84.93, en: 'Perfect. Let\'s get him a pen.', vi: '' },
			{ t: 87.64, e: 92.85, en: '4. Do you see anything here that we can get to take to Jason and Alison\'s wedding?', vi: '' },
			{ t: 93.50, e: 96.63, en: 'Not really. Can\'t we just bring them some flowers?', vi: '' },
			{ t: 97.20, e: 102.91, en: 'No. Flowers aren\'t right for a wedding. We have to bring them something nice for their home.', vi: '' },
			{ t: 103.54, e: 104.49, en: 'Oh, I see.', vi: '' },
			{ t: 105.10, e: 106.99, en: 'Hey, how about this tape pot?', vi: '' },
			{ t: 107.62, e: 110.49, en: 'Yeah, that looks nice. Let\'s get it.', vi: '' },
			{ t: 112.24, e: 116.57, en: '5. That was nice of the Roberts to invite us to dinner.', vi: '' },
			{ t: 117.16, e: 119.63, en: 'Yes, and we need to bring something.', vi: '' },
			{ t: 120.26, e: 121.43, en: 'Like a hostess gift?', vi: '' },
			{ t: 121.96, e: 122.63, en: 'Exactly.', vi: '' },
			{ t: 123.38, e: 125.71, en: 'What about that tea pot we saw at the store today?', vi: '' },
			{ t: 126.38, e: 131.73, en: 'Well, for dinner, you usually bring something a little less expensive, like...', vi: '' },
			{ t: 132.28, e: 133.43, en: 'Like flowers?', vi: '' },
			{ t: 134.10, e: 134.65, en: 'Perfect.', vi: '' },
			{ t: 136.92, e: 137.63, en: '6.', vi: '' },
			{ t: 138.30, e: 141.91, en: 'I\'m trying to think of a gift for my dad for Father\'s Day.', vi: '' },
			{ t: 142.48, e: 143.35, en: 'Any ideas?', vi: '' },
			{ t: 144.10, e: 145.19, en: 'How about a pen?', vi: '' },
			{ t: 145.82, e: 148.91, en: 'That\'s a good idea, but he has so many pens.', vi: '' },
			{ t: 149.76, e: 152.81, en: 'I see. What about a tie?', vi: '' },
			{ t: 154.02, e: 157.79, en: 'Yeah. He certainly needs ties to wear to work.', vi: '' },
			{ t: 158.32, e: 162.57, en: 'Okay. Let\'s go to the department store. I\'ll help you pick one out.', vi: '' },
		]
